#define CPS2_ROM_BASE          0x00000000  /* 4MB Program ROM (Banks 03-10) */
#define CPS2_ROM_END           0x003FFFFF

#define CPS2_INPUT_BASE        0x00400000  /* Memory-mapped I/O & Controls */
#define CPS2_INPUT_P1_P2       0x00400000  /* 16-bit: Player 1 & 2 inputs */
#define CPS2_INPUT_P3_P4       0x00400002  /* 16-bit: Player 3 & 4 inputs */
#define CPS2_INPUT_SYSTEM      0x00400004  /* Coins, Service, Test switch */

#define CPS2_PALETTE_BASE      0x00660000  /* CPS2 Palette RAM (RGB555) */
#define CPS2_PALETTE_SIZE      0x00004000  /* 16 KB (4096 colors) */

#define CPS2_OBJ_BASE          0x00700000  /* Object / Sprite RAM */
#define CPS2_OBJ_SIZE          0x00008000  /* 32 KB (1024 sprites x 8 bytes) */

#define CPS2_REG_BASE          0x00708000  /* Video & Raster Control Registers */
#define CPS2_REG_SCROLL1_X     0x00708000
#define CPS2_REG_SCROLL1_Y     0x00708002
#define CPS2_REG_SCROLL2_X     0x00708004
#define CPS2_REG_SCROLL2_Y     0x00708006
#define CPS2_REG_SCROLL3_X     0x00708008
#define CPS2_REG_SCROLL3_Y     0x0070800A
#define CPS2_REG_LAYER_CTRL    0x0070800C  /* Layer priority & enable mask */

#define CPS2_QSOUND_DATA       0x00804000  /* QSound 16-bit Communication Port */
#define CPS2_QSOUND_STATUS     0x00804040  /* QSound Ready / Busy Status */

#define CPS2_RAM_BASE          0x00FF0000  /* 64 KB Main Work RAM */
#define CPS2_RAM_END           0x00FFFFFF

/* ============================================================================
 * 2. CPS-2 SPRITE OBJECT STRUCTURE (8 Bytes per Object)
 * ============================================================================ */
typedef struct __attribute__((packed)) {
    uint16_t x_pos;       /* Bits 0-8: X coordinate, Bit 9: End-of-list flag */
    uint16_t y_pos;       /* Bits 0-8: Y coordinate, Bits 9-10: Sprite size */
    uint16_t tile_code;   /* Bits 0-14: Tile index in 64-bit GFX ROMs */
    uint16_t attribute;   /* Bit 0-4: Palette bank, Bit 5: Flip X, Bit 6: Flip Y, Bit 7: Priority */
} cps2_sprite_t;

